<?php $summary=$page['summary']; ?>
<section class="contact-sheet direct-supply" data-day-summary><h2>Jornada <?= $e($summary['date']) ?></h2>
<h3>Cobros asociados a las ventas</h3><div class="direct-stock-table"><table><thead><tr><th>Moneda</th><th>Registrado</th><th>Confirmado</th><th>En revisión</th><th>Reembolsos</th><th>Efectivo esperado</th></tr></thead><tbody><?php foreach($summary['money'] as $code=>$totals): ?><tr><td><?= $e($code) ?></td><td><?= $e($totals['registered']) ?></td><td><?= $e($totals['settled']) ?></td><td><?= $e($totals['pending']) ?></td><td><?= $e($totals['refunds']) ?></td><td><?= $e($totals['cash']) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="section-subtitle">El efectivo esperado corresponde a cobros y reembolsos de caja registrados por este vendedor. No incluye cobros hechos por el administrador, fondos iniciales ni gastos de caja.</p>
<?php foreach($summary['payments'] as $p): ?><p><?= $p['direction']==='outbound'?'Reembolso: ':'Cobro: ' ?><?= $e($p['name'].' · '.$p['account_name'].' · '.$p['method_name'].' · '.$p['amount'].' '.$p['currency_code']) ?> · <?= $p['status']==='settled'?'Confirmado':'En revisión' ?></p><?php endforeach; ?>
<h3>Ventas de la jornada</h3><?php foreach($summary['sales'] as $sale): ?><p><?= $e($sale['name'].' · '.$sale['total_amount'].' '.$sale['currency_code']) ?> · Vence <?= $e($sale['due_date']) ?> · Saldo sin confirmar: <?= $e($sale['balance']) ?> · En revisión: <?= $e($sale['pending']) ?></p><?php endforeach; ?><?php if(!$summary['sales']): ?><p>No hay ventas registradas en esta fecha.</p><?php endif; ?>
<h3>Mercancía movida en la jornada</h3><div class="direct-stock-table"><table><thead><tr><th>Producto</th><th>Recibido</th><th>Vendido</th><th>Devuelto por cliente</th><th>Retornado al almacén</th></tr></thead><tbody><?php foreach($summary['stock'] as $row): ?><tr><td><?= $e($row['name']) ?></td><td><?= $e($row['received']) ?></td><td><?= $e($row['sold']) ?></td><td><?= $e($row['client_return']) ?></td><td><?= $e($row['returned']) ?></td></tr><?php endforeach; ?></tbody></table></div>
<h3>Existencias al generar este resumen</h3><p class="section-subtitle">Capturadas: <?= $e($summary['captured_at']) ?>. Son las existencias en la ubicación asignada al vendedor al generar el resumen.</p><?php foreach($summary['inventory_at_submission'] as $row): ?><p><?= $e($row['name']) ?> · A la mano: <?= $e($row['on_hand']) ?> · Disponible: <?= $e($row['available']) ?></p><?php endforeach; ?>
<h3>Comisiones de las ventas de la jornada</h3><?php foreach($summary['commissions'] as $row): ?><p><?= $e($row['invoice']) ?> · Generada: <?= $e($row['generated'].' '.$row['currency']) ?> · Habilitada por cobros confirmados: <?= $e($row['earned'].' '.$row['currency']) ?></p><?php endforeach; ?>
</section>
